/**
 * Generates each program's `agent-prompts.ts` from its `agent/*.md`, so the
 * bundle and `pnpm try` both carry the prompts as plain strings. Run with
 * `pnpm bundle:agent-prompts` after editing a prompt; a test fails while a
 * generated module is stale.
 */

import { execFileSync } from 'child_process';
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const PROGRAMS = path.resolve(
  path.dirname(fileURLToPath(import.meta.url)),
  '..',
  'src',
  'programs',
);

export const GENERATED_HEADER =
  '// Generated by `pnpm bundle:agent-prompts` from ./agent/*.md. Do not edit.';

const written: string[] = [];
for (const program of fs.readdirSync(PROGRAMS)) {
  const agentDir = path.join(PROGRAMS, program, 'agent');
  if (!fs.existsSync(agentDir)) continue;
  const files = fs
    .readdirSync(agentDir)
    .filter((file) => file.endsWith('.md'))
    .sort();
  const entries = files.map(
    (file) =>
      `  ${JSON.stringify(file.replace(/\.md$/, ''))}: ${JSON.stringify(
        fs.readFileSync(path.join(agentDir, file), 'utf8'),
      )},`,
  );
  const out = path.join(PROGRAMS, program, 'agent-prompts.ts');
  fs.writeFileSync(
    out,
    `${GENERATED_HEADER}\n\n/** This program's agent prompts by task type, verbatim. */\nexport const AGENT_PROMPTS: Readonly<Record<string, string>> = {\n${entries.join(
      '\n',
    )}\n};\n`,
  );
  written.push(out);
}

execFileSync('pnpm', ['exec', 'prettier', '--write', ...written], {
  stdio: 'inherit',
});
console.log(`Generated ${written.length} agent-prompt modules.`);
